const RATE_DEFS=[
 {k:"v_scan_clean", l:"Vendor scanning \u2014 clean documents", u:"$/page", d:0.07, c:"Vendor Service Rates", s:"SecureScan / Record Nations low end ($0.07\u20130.12)"},
 {k:"v_scan_avg", l:"Vendor scanning \u2014 average condition", u:"$/page", d:0.10, c:"Vendor Service Rates", s:"Midpoint of $0.07\u20130.12 industry cluster"},
 // ...
 {k:"w_scan", l:"Student wage \u2014 prep & scanning operator", u:"$/hr", d:15.50, c:"BU Student Labor", s:"BU SEO Job Classification ($15.00\u201315.50 tiers)"},
 {k:"fringe_pct", l:"Payroll fringe on student labor", u:"%", d:0, c:"BU Student Labor", s:"Students FICA-exempt while enrolled (IRC \u00a73121(b)(10)); use 7.65 for summer"},
 {k:"h_scanner", l:"Production scanner (Ricoh fi-8170, TWAIN/ISIS)", u:"$/unit", d:1050, c:"Hardware & Software", s:"Street price ~$1,050; 70 ppm, 10,000 pages/day duty"},
 {k:"rework_pct", l:"Two-step rework / inconsistency factor", u:"%", d:15, c:"Internal Project Effort", s:"Adapting Phase-1 output to Phase-2 import & re-QC", a:1},
];

function loadRates(){
  const base={}; RATE_DEFS.forEach(d=>base[d.k]=d.d);
  try{ const saved=JSON.parse(localStorage.getItem(LS_RATES)||"{}");
       Object.keys(saved).forEach(k=>{ if(k in base && isFinite(+saved[k])) base[k]=+saved[k]; });
  }catch(e){}
  R=base;
}

function gather(){
  const g=id=>document.getElementById(id);
  const boxes=+g("i_boxes").value||0, ppb=+g("i_ppb").value||2500;
  const ovr=+g("i_pagesOverride").value||0;
  const pages=ovr>0?ovr:boxes*ppb;
  return {
    boxes, ppb, pages,
    idxbasis:g("i_idxbasis").value,
    ppd:Math.max(1,+g("i_ppd").value||5),
    ppbundle:Math.max(1,+g("i_ppbundle").value||100),
    cond:g("i_cond").value, idx:g("i_idx").value,
    ocr:g("i_ocr").checked, destruct:g("i_destruct").checked,
    students:Math.max(1,+g("i_students").value||1),
    hpw:Math.max(1,+g("i_hpw").value||20),
    hy:{ pickup:g("b_pickup").value, prep:g("b_prep").value, scan:g("b_scan").value,
         soft:g("b_soft").value, equip:g("b_equip").value, ocr:g("b_ocr").value,
         index:g("b_index").value, qc:g("b_qc").value, store:g("b_store").value,
         boxstore:g("b_boxstore").value, destruct:g("b_destruct").value }
  };
}

function calc(inp){
  const p=inp.pages;
  const bundleMode=inp.idxbasis==="bundle";
  const docs=bundleMode?Math.max(1,Math.ceil(p/inp.ppbundle)):Math.ceil(p/inp.ppd);
  const unitLabel=bundleMode?"bundles":"documents";
  const fringe=1+R.fringe_pct/100;
  const cap=inp.students*inp.hpw; // student hours/week
  const highVol=p>=100000;
  const scanRate=highVol?R.v_scan_highvol:{clean:R.v_scan_clean,avg:R.v_scan_avg,complex:R.v_scan_complex}[cond];
  const prepRate={clean:R.v_prep_clean,avg:R.v_prep_avg,complex:R.v_prep_complex}[cond];
  const idxRate={basic:R.v_index_basic,std:R.v_index_std,deep:R.v_index_deep}[idx];
  const trips=Math.max(1,Math.ceil(inp.boxes/40));

const A={name:"Scenario A \u2014 3rd-Party Vendor Full Service",items:[],cls:"A"};
A.items.push(li("Vendor: scanning"+(highVol?" (high-volume tier)":""),p,"pages",scanRate,p*scanRate));
A.items.push(li("Vendor: document prep",p,"pages",prepRate,p*prepRate));
if(inp.ocr) A.items.push(li("Vendor: OCR searchable layer",p,"pages",R.v_ocr,p*R.v_ocr));
A.items.push(li("Vendor: indexing ("+idx+")",p,"pages",idxRate,p*idxRate));
let svc=A.items.reduce((s,i)=>s+i.amt,0);
if(svc<R.v_min){A.items.push(li("Vendor: minimum project fee adjustment",1,"flat",R.v_min-svc,R.v_min-svc));svc=R.v_min;}
A.items.push(li("BU: vendor procurement / RFP / contract",R.e_proc_vendor,"hrs",R.e_staff,R.e_proc_vendor*R.e_staff));
A.total=A.items.reduce((s,i)=>s+i.amt,0);
A.weeks=R.d_vendor_lead+R.d_vendor_turn;

let buHrs=0; let vendorUsed=false;
// prep
if(hy.prep==="vendor"){ B.items.push(li("Vendor: document prep",p,"pages",prepRate,p*prepRate)); vendorUsed=true; }
else { B.items.push(li("BU Students: document prep",Math.ceil(prepHrs),"hrs",R.w_scan*fringe,prepHrs*R.w_scan*fringe)); buHrs+=prepHrs; }
// scanning
let buScans=(hy.scan==="bu");
if(!buScans){ B.items.push(li("Vendor: scanning",p,"pages",scanRate,p*scanRate)); vendorUsed=true; }
else { B.items.push(li("BU Students: scanning to PDF",Math.ceil(scanHrs),"hrs",R.w_scan*fringe,scanHrs*R.w_scan*fringe)); buHrs+=scanHrs; }

if(vendorUsed) B.items.push(li("BU: vendor/software contract procurement",R.e_proc_pv,"hrs",R.e_staff,R.e_proc_pv*R.e_staff));
B.items.push(li("BU: project management \u2014 Phase 1 (scanning project)",R.e_pm,"hrs",R.e_staff,R.e_pm*R.e_staff));
B.items.push(li("BU: DRIP/import configuration into OnBase",R.e_drip,"hrs",R.e_staff,R.e_drip*R.e_staff));
B.items.push(li("BU: project management \u2014 Phase 2 (OnBase project)",R.e_pm,"hrs",R.e_staff,R.e_pm*R.e_staff));
const reworkHrs=buHrs*R.rework_pct/100;
if(reworkHrs>0) B.items.push(li(`Rework / inconsistency between phases (${R.rework_pct}% of student hrs)`,Math.ceil(reworkHrs),"hrs",R.w_index*fringe,reworkHrs*R.w_index*fringe));

const C={name:"Scenario C \u2014 In-House: Students Scan & Index Directly into OnBase",items:[],cls:"C"};
C.items.push(li("BU Students: document prep",Math.ceil(prepHrs),"hrs",R.w_scan*fringe,prepHrs*R.w_scan*fringe));
C.items.push(li("BU Students: scan + index into OnBase scan queue (one pass)",Math.ceil(siHrs),"hrs",R.w_index*fringe,siHrs*R.w_index*fringe));
if(hw>0) C.items.push(li("BU: scanning workstation(s) \u2014 Ricoh fi-8170 class",inp.scanners,"unit(s)",R.h_scanner,hw));
C.items.push(li("BU: OnBase scan queue setup (Document Imaging & Services)",R.e_queue,"hrs",R.e_staff,R.e_queue*R.e_staff));
const stuHrsC=prepHrs+siHrs;
const cwks=stuHrsC/cap;
C.weeks=R.d_queue_lead+cwks;

const prepTp={clean:R.t_prep_clean,avg:R.t_prep_avg,complex:R.t_prep_complex}[cond];
const prepHrs=p/prepTp;
const scanHrs=p/R.t_scan;
const idxTp={basic:R.t_index_basic,std:R.t_index_std,deep:R.t_index_deep}[idx];
const idxHrs=docs/idxTp;
const siTp={basic:R.t_si_basic,std:R.t_si_std,deep:R.t_si_deep}[idx];
const siHrs=p/siTp;
const hw=inp.ownScanner?0:inp.scanners*R.h_scanner;

const svA=A.total-C.total, svB=B.total-C.total;
const cheapest=[A,B,C].reduce((m,s)=>s.total<m.total?s:m);
if(cheapest===C){
  h+=`<div class="savings">\u2705 <b>In-house direct-to-OnBase (Scenario C) is the lowest-cost option...</b><br>
    Savings vs. vendor full service: <b>${fmt$(svA)}</b> (${(svA/A.total*100).toFixed(0)}%) ...
    Time saved vs. hybrid: <b>${fmt1(B.weeks-C.weeks)} weeks</b> ...</div>`;
}else{
  h+=`<div class="savings" style="background:#fff7ec;...">\u26a0\ufe0f For this volume/profile, <b>${cheapest.name.split("\u2014")[0].trim()}</b> is the lowest-cost option ...</div>`;
}

if(inp.budget>0){
  const order=[{s:A,...},{s:B,...},{s:C,...}].sort((x,y)=>x.s.total-y.s.total);
  const fit=order.filter(o=>o.s.total<=inp.budget);
  let verdict;
  if(fit.length){
    const pick=fit[0]; // lowest-cost scenario that fits = best value within budget
    verdict=`\u2705 <b>Recommended within budget: ${pick.n.split("\u00b7")[1].trim()}</b> at <b>${fmt$(pick.s.total)}</b> ...`;
  }else{
    const closest=order[0];
    verdict=`\u26a0\ufe0f <b>No scenario fits the ${fmt$(inp.budget)} budget.</b> The lowest-cost option is ... ${fmt$(closest.s.total-inp.budget)} over ...`;
  }
}

const PAGE_MAX=1040;  // px of content before flowing to the next page (~11in)
const isHeading=el=>el&&el.nodeType===1&&/^H[1-6]$/.test(el.tagName);
let page=mk();
blocks.forEach(b=>{
  page.appendChild(b);
  if(page.scrollHeight>PAGE_MAX && page.children.length>1){
    page.removeChild(b);
    const carry=[];
    while(page.lastChild && isHeading(page.lastChild) && page.children.length>1){
      carry.unshift(page.removeChild(page.lastChild)); // keep-with-next
    }
    page=mk(); carry.forEach(c=>page.appendChild(c)); page.appendChild(b);
  }
});

function memStore(){
  const m={};
  return { getItem:k=>(k in m?m[k]:null), setItem:(k,v)=>{m[k]=String(v);},
           removeItem:k=>{delete m[k];}, clear:()=>{for(const k in m) delete m[k];} };
}
function safe(read){
  try{ const s=read(); const t="__budct_probe"; s.setItem(t,"1"); s.removeItem(t); return s; }
  catch(e){ return memStore(); }
}
try{ Object.defineProperty(window,"localStorage",{value:safe(()=>window.localStorage),configurable:true}); }catch(e){}
